from xml.sax.saxutils import escape
ppt=R/'交付/宫门之内的奔跑_展示稿.pptx'
with zipfile.ZipFile(ppt) as z: entries=[(n,z.read(n)) for n in z.infolist()]
counts=[]
for entry,(info,data) in enumerate(entries):
 match=re.fullmatch(r'ppt/slides/slide(\d+)\.xml',info.filename)
 note=re.fullmatch(r'ppt/notesSlides/notesSlide(\d+)\.xml',info.filename)
 if match:
  i=int(match[1])-1;mapping={old[i]['title']:new[i]['title'],**dict(zip(old[i]['body'],new[i]['body']))};hits=[]
  def sub(m):
   value=html.unescape(m[1]);replacement=mapping.get(value,value)
   if value in mapping:hits.append(value)
   return '<a:t>'+escape(replacement)+'</a:t>'
  text=re.sub(r'<a:t>(.*?)</a:t>',sub,data.decode('utf-8'),flags=re.S);data=text.encode('utf-8');counts.append({'slide':i+1,'matched':len(hits)})
 elif note:
  i=int(note[1])-1;d=new[i];refs=json.loads((R/'工具/sources.json').read_text(encoding='utf-8'));content=f"讲者：{d['speaker']}；预算：{d['minutes']}分钟。\n\n【讲述】\n{d['notes']}\n\n【排练备忘，不朗读】\n{d['prep']}\n\n【来源】\n"+'\n'.join(refs[k] for k in d['sources'])
  text=data.decode('utf-8').replace('<p:notes xmlns:p=', '<p:notes xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:p=',1);done=[False]
  def block(m):
   b=m[0]
   if not done[0] and 'type="body"' in b:
    b=re.sub(r'<a:p>.*?</a:p>',lambda _: '<a:p><a:r><a:rPr lang="zh-CN"/><a:t>'+escape(content)+'</a:t></a:r></a:p>',b,count=1,flags=re.S)
    # Existing body may have many paragraphs; replace entire txBody while keeping its properties.
    b=re.sub(r'(<p:txBody>.*?<a:lstStyle[^>]*(?:/>|>.*?</a:lstStyle>)).*?(</p:txBody>)',lambda x:x[1]+'<a:p><a:r><a:rPr lang="zh-CN"/><a:t>'+escape(content)+'</a:t></a:r></a:p>'+x[2],b,flags=re.S)
    done[0]=True
   return b
  text=re.sub(r'<p:sp>.*?</p:sp>',block,text,flags=re.S)
  if not done[0]:raise RuntimeError('notes body missing '+str(i+1))
  data=text.encode('utf-8')
 entries[entry]=(info,data)
with zipfile.ZipFile(ppt,'w',zipfile.ZIP_DEFLATED) as z:
 for info,data in entries:z.writestr(info,data)
(R/'制作记录/语言修订记录.json').write_text(json.dumps({'time':datetime.datetime.now().astimezone().isoformat(),'slides':counts,'basis':'课程第三部分25—39、55—57页；原思路文件','scope':'23页文字与讲者备注；讲述与排练备忘分开；保持素材及版式'},ensure_ascii=False,indent=2),encoding='utf-8')
print('Revised 23 slides and notes',counts)
